interface MembershipPlan{double calculateFee(double base);}class Monthly implements MembershipPlan{public double calculateFee(double b){return b;}}class Quarterly implements MembershipPlan{public double calculateFee(double b){return b*3*.90;}}class Annual implements MembershipPlan{public double calculateFee(double b){return b*12*.75;}}enum Status{ACTIVE,FROZEN,EXPIRED}class Member{String name;Member(String n){name=n;}}class Membership{Member member;MembershipPlan plan;Status status=Status.ACTIVE;Membership(Member m,MembershipPlan p){member=m;plan=p;}double fee(){return plan.calculateFee(1000);}void checkIn(){if(status!=Status.ACTIVE)throw new IllegalStateException();}void freeze(){if(status!=Status.ACTIVE)throw new IllegalStateException();status=Status.FROZEN;}void unfreeze(){if(status!=Status.FROZEN)throw new IllegalStateException();status=Status.ACTIVE;}void expire(){status=Status.EXPIRED;}}public class Main{public static void main(String[]a){}}